export function price() { return 12 }
export async function servicePrice(url: string) {
  return (await (await fetch(url)).json()).price
}

const orders: number[] = []
export function postOrder(quantity: number, unitPrice = price()) {
  const subtotal = unitPrice * quantity
  const total = subtotal * (quantity > 5 ? 0.9 : 1)
  orders.push(total)
  return { status: 201, total }
}

